select case when amount >= 1620 then 'HIGH' else 'LOW' end as amount_tier, date_trunc('year', paid_at) as year_start, approx_percentile(amount, 0.9) as amount_p90, sum(case when method = 'paypal' then amount else 0 end) as paypal_amount, size(collect_set(method)) as num_methods, min(amount) as min_amount, round(avg(amount), 2) as avg_amount, count(*) as num_rows from payments group by grouping sets ((case when amount >= 1620 then 'HIGH' else 'LOW' end, date_trunc('year', paid_at)), (case when amount >= 1620 then 'HIGH' else 'LOW' end), ()) having min(amount) >= 0 order by year_start desc;
